+fn cmd_add(root: &ArgMatches<'_>, matches: &ArgMatches<'_>) -> Result<(), String> {
+    let path = resolve_config_path_for_read(root)?;
+    let mut config = read_config(&path)?;
+    let alias = matches.value_of("alias").unwrap();
+    let force = matches.is_present("force");
+
+    if config.scripts.contains_key(alias) && !force {
+        return Err(alias_exists_error(alias));
+    }
+
+    let command = match matches.value_of("command") {
+        Some(command) => command.to_owned(),
+        None => edit_text("".to_owned())?,
+    };
+
+    let script = ScriptEntry {
+        command,
+        description: matches.value_of("description").map(ToOwned::to_owned),
+        tags: matches
+            .values_of("tags")
+            .map(|values| values.map(ToOwned::to_owned).collect())
+            .unwrap_or_default(),
+    };
+
+    config.scripts.insert(alias.to_owned(), script);
+    write_config(&path, &config)?;
+    println!("Added {}", alias);
+    Ok(())
+}
