use clap::{App, AppSettings, Arg, ArgMatches, SubCommand};
use serde::Deserialize;
use std::collections::BTreeMap;
use std::env;
use std::fs;
use std::io;
use std::path::{Path, PathBuf};
use std::process::{self, Command};
use tempfile::NamedTempFile;

const APP_NAME: &str = "pier";
const VERSION: &str = "0.1.6";
const AUTHORS: &str = "Benjamin Scholtz, Isak Johansson";
const ABOUT: &str = "A simple script management CLI";
const NO_SCRIPTS_ERROR: &str = "No scripts exist. Would you like to add a new script?";
const CONFIG_FILE_HELP_LONG: &str = "Sets a custom config file.\n\
\n\
DEFAULT PATH is otherwise determined in this order:\n\
\n\
- $PIER_CONFIG_PATH (environment variable if set)\n\
\n\
- pier.toml (in the current directory)\n\
\n\
- $XDG_CONFIG_HOME/pier/config.toml\n\
\n\
- $XDG_CONFIG_HOME/pier/config\n\
\n\
- $XDG_CONFIG_HOME/pier.toml\n\
\n\
- $HOME/.pier.toml\n\
\n\
- $HOME/.pier";

#[derive(Clone, Debug, Default, Deserialize)]
struct ConfigFile {
    #[serde(default)]
    scripts: BTreeMap<String, ScriptEntry>,
}

#[derive(Clone, Debug, Default, Deserialize)]
struct ScriptEntry {
    command: String,
    #[serde(default)]
    description: Option<String>,
    #[serde(default)]
    tags: Vec<String>,
}

#[derive(Clone, Debug)]
struct ListedScript {
    alias: String,
    tags: String,
    description: String,
    command_lines: Vec<String>,
}

fn main() {
    let matches = build_app().get_matches();

    let exit_code = match dispatch(&matches) {
        Ok(code) => code,
        Err(message) => {
            eprintln!("error: {}", message);
            1
        }
    };

    process::exit(exit_code);
}

fn build_app() -> App<'static, 'static> {
    App::new(APP_NAME)
        .about(ABOUT)
        .author(AUTHORS)
        .setting(AppSettings::ColoredHelp)
        .setting(AppSettings::DontCollapseArgsInUsage)
        .version(VERSION)
        .arg(
            Arg::with_name("verbose")
                .short("v")
                .long("verbose")
                .help("The level of verbosity")
                .multiple(true),
        )
        .arg(
            Arg::with_name("config-file")
                .short("c")
                .long("config-file")
                .value_name("path")
                .help("Sets a custom config file.")
                .long_help(CONFIG_FILE_HELP_LONG),
        )
        .arg(
            Arg::with_name("alias")
                .index(1)
                .help("The alias or name for the script."),
        )
        .arg(
            Arg::with_name("args")
                .index(2)
                .multiple(true)
                .help("The positional arguments to send to script."),
        )
        .subcommand(
            subcommand("add", "Add a new script to config.")
                .arg(
                    Arg::with_name("force")
                        .short("f")
                        .long("force")
                        .help("Allows to overwrite the existing script"),
                )
                .arg(
                    Arg::with_name("alias")
                        .short("a")
                        .long("alias")
                        .value_name("alias")
                        .required(true)
                        .help("The alias or name for the script."),
                )
                .arg(
                    Arg::with_name("description")
                        .short("d")
                        .long("description")
                        .value_name("description")
                        .help("The description for the script."),
                )
                .arg(
                    Arg::with_name("tags")
                        .short("t")
                        .long("tag")
                        .value_name("tags")
                        .multiple(true)
                        .takes_value(true)
                        .help("Set which tags the script belongs to."),
                )
                .arg(
                    Arg::with_name("command")
                        .help("The command/script content to be executed. If this argument is not found it will open your $EDITOR\nfor you to enter the script into."),
                ),
        )
        .subcommand(
            subcommand(
                "config-init",
                "alias: init - Add a config file.",
            )
            .alias("init"),
        )
        .subcommand(
            subcommand("copy", "alias: cp - Copy existing alias to the new one")
                .alias("cp")
                .arg(
                    Arg::with_name("from-alias")
                        .required(true)
                        .help("The alias of the script that will be copied."),
                )
                .arg(
                    Arg::with_name("to-alias")
                        .required(true)
                        .help("The new alias of the copy of the script."),
                ),
        )
        .subcommand(
            subcommand("edit", "Edit a script matching alias.").arg(
                Arg::with_name("alias")
                    .required(true)
                    .help("The alias or name for the script."),
            ),
        )
        .subcommand(
            subcommand(
                "list",
                "alias: ls - List scripts\n\nDisplay options are determined by priority in this order:\n\n1. List only aliases\n\n2. Show full command\n\n3. Command display with (cli option)\n\n4. Command display with (config option)",
            )
            .alias("ls")
            .arg(
                Arg::with_name("cmd_full")
                    .short("l")
                    .long("cmd_full")
                    .help("Display the full command."),
            )
            .arg(
                Arg::with_name("list_aliases")
                    .short("q")
                    .long("list_aliases")
                    .help("Only displays aliases of the scripts."),
            )
            .arg(
                Arg::with_name("cmd_width")
                    .short("c")
                    .long("cmd_width")
                    .value_name("cmd-width")
                    .help("The max number of characters to display from the command."),
            )
            .arg(
                Arg::with_name("tags")
                    .short("t")
                    .long("tag")
                    .value_name("tags")
                    .multiple(true)
                    .takes_value(true)
                    .help("Filter based on tags."),
            ),
        )
        .subcommand(
            subcommand(
                "move",
                "alias: mv, rename - Move/rename existing alias to the new one",
            )
            .aliases(&["mv", "rename"])
            .arg(
                Arg::with_name("force")
                    .short("f")
                    .long("force")
                    .help("Allows to overwrite the existing script"),
            )
            .arg(
                Arg::with_name("from-alias")
                    .required(true)
                    .help("The alias of the script that will be moved."),
            )
            .arg(
                Arg::with_name("to-alias")
                    .required(true)
                    .help("The new alias of the script."),
            ),
        )
        .subcommand(
            subcommand("remove", "alias: rm - Remove a script matching alias.")
                .alias("rm")
                .arg(
                    Arg::with_name("alias")
                        .required(true)
                        .help("The alias or name for the script."),
                ),
        )
        .subcommand(
            subcommand("run", "Run a script matching alias.")
                .arg(
                    Arg::with_name("alias")
                        .required(true)
                        .help("The alias or name for the script."),
                )
                .arg(
                    Arg::with_name("args")
                        .multiple(true)
                        .help("The positional arguments to send to script."),
                ),
        )
        .subcommand(
            subcommand("show", "Show a script matching alias.").arg(
                Arg::with_name("alias")
                    .required(true)
                    .help("The alias or name for the script."),
            ),
        )
}

fn subcommand(name: &'static str, about: &'static str) -> App<'static, 'static> {
    SubCommand::with_name(name)
        .about(about)
        .setting(AppSettings::ColoredHelp)
        .setting(AppSettings::DontCollapseArgsInUsage)
        .version(VERSION)
}

fn dispatch(matches: &ArgMatches<'_>) -> Result<i32, String> {
    if let Some(sub_matches) = matches.subcommand_matches("add") {
        return cmd_add(matches, sub_matches).map(|_| 0);
    }
    if let Some(_) = matches.subcommand_matches("config-init") {
        return cmd_config_init(matches).map(|_| 0);
    }
    if let Some(sub_matches) = matches.subcommand_matches("copy") {
        return cmd_copy(matches, sub_matches).map(|_| 0);
    }
    if let Some(sub_matches) = matches.subcommand_matches("edit") {
        return cmd_edit(matches, sub_matches).map(|_| 0);
    }
    if let Some(sub_matches) = matches.subcommand_matches("list") {
        return cmd_list(matches, sub_matches).map(|_| 0);
    }
    if let Some(sub_matches) = matches.subcommand_matches("move") {
        return cmd_move(matches, sub_matches).map(|_| 0);
    }
    if let Some(sub_matches) = matches.subcommand_matches("remove") {
        return cmd_remove(matches, sub_matches).map(|_| 0);
    }
    if let Some(sub_matches) = matches.subcommand_matches("run") {
        return cmd_run(matches, sub_matches);
    }
    if let Some(sub_matches) = matches.subcommand_matches("show") {
        return cmd_show(matches, sub_matches).map(|_| 0);
    }

    let alias = match matches.value_of("alias") {
        Some(alias) => alias,
        None => {
            eprintln!("error: The following required arguments were not provided:");
            eprintln!("    <alias>");
            eprintln!();
            eprintln!("USAGE:");
            eprintln!("    executable [FLAGS] [OPTIONS] <alias> [args]...");
            eprintln!("    executable [FLAGS] [OPTIONS] <SUBCOMMAND>");
            eprintln!();
            eprintln!("For more information try --help");
            return Ok(1);
        }
    };

    let args = matches
        .values_of("args")
        .map(|values| values.map(ToOwned::to_owned).collect::<Vec<_>>())
        .unwrap_or_default();

    run_alias(matches, alias, &args)
}

fn cmd_add(root: &ArgMatches<'_>, matches: &ArgMatches<'_>) -> Result<(), String> {
    let path = resolve_config_path_for_read(root)?;
    let mut config = read_config(&path)?;
    let alias = matches.value_of("alias").unwrap();
    let force = matches.is_present("force");

    if config.scripts.contains_key(alias) && !force {
        return Err(alias_exists_error(alias));
    }

    let command = match matches.value_of("command") {
        Some(command) => command.to_owned(),
        None => edit_text("".to_owned())?,
    };

    let script = ScriptEntry {
        command,
        description: matches.value_of("description").map(ToOwned::to_owned),
        tags: matches
            .values_of("tags")
            .map(|values| values.map(ToOwned::to_owned).collect())
            .unwrap_or_default(),
    };

    config.scripts.insert(alias.to_owned(), script);
    write_config(&path, &config)?;
    println!("Added {}", alias);
    Ok(())
}

fn cmd_config_init(root: &ArgMatches<'_>) -> Result<(), String> {
    let path = resolve_config_path_for_init(root)?;

    if path.exists() {
        return Err(format!(
            "Cannot initialize config at {}, file already exists.",
            path.display()
        ));
    }

    if let Some(parent) = path.parent() {
        if !parent.as_os_str().is_empty() && !parent.exists() {
            fs::create_dir(parent)
                .map_err(|err| format!("Failed to create directory. {}", err))?;
        }
    }

    let mut config = ConfigFile::default();
    config.scripts.insert(
        "hello-pier".to_owned(),
        ScriptEntry {
            command: "echo Hello, Pier!".to_owned(),
            description: Some("This is an example command.".to_owned()),
            tags: Vec::new(),
        },
    );

    write_config(&path, &config)?;
    println!("Added hello-pier");
    Ok(())
}

fn cmd_copy(root: &ArgMatches<'_>, matches: &ArgMatches<'_>) -> Result<(), String> {
    let path = resolve_config_path_for_read(root)?;
    let mut config = read_config(&path)?;
    ensure_scripts_exist(&config)?;

    let from_alias = matches.value_of("from-alias").unwrap();
    let to_alias = matches.value_of("to-alias").unwrap();

    if config.scripts.contains_key(to_alias) {
        return Err(alias_exists_error(to_alias));
    }

    let script = match config.scripts.get(from_alias).cloned() {
        Some(script) => script,
        None => return Err(alias_not_found_error(from_alias)),
    };

    config.scripts.insert(to_alias.to_owned(), script);
    write_config(&path, &config)?;
    println!("Copy from alias {} to new alias {}", from_alias, to_alias);
    Ok(())
}

fn cmd_edit(root: &ArgMatches<'_>, matches: &ArgMatches<'_>) -> Result<(), String> {
    let path = resolve_config_path_for_read(root)?;
    let mut config = read_config(&path)?;
    ensure_scripts_exist(&config)?;

    let alias = matches.value_of("alias").unwrap();
    let existing = match config.scripts.get(alias).cloned() {
        Some(script) => script,
        None => return Err(alias_not_found_error(alias)),
    };

    let mut updated = existing;
    updated.command = edit_text(updated.command.clone())?;
    config.scripts.insert(alias.to_owned(), updated);
    write_config(&path, &config)?;
    println!("Edited {}", alias);
    Ok(())
}

fn cmd_list(root: &ArgMatches<'_>, matches: &ArgMatches<'_>) -> Result<(), String> {
    let path = resolve_config_path_for_read(root)?;
    let config = read_config(&path)?;
    ensure_scripts_exist(&config)?;

    let tag_filters = matches
        .values_of("tags")
        .map(|values| values.map(ToOwned::to_owned).collect::<Vec<_>>())
        .unwrap_or_default();
    let list_aliases = matches.is_present("list_aliases");
    let cmd_width = matches
        .value_of("cmd_width")
        .and_then(|value| value.parse::<usize>().ok());

    let scripts = listed_scripts(&config, &tag_filters, cmd_width);

    if list_aliases {
        for script in scripts {
            println!("{}", script.alias);
        }
        return Ok(());
    }

    print_list_table(&scripts);
    Ok(())
}

fn cmd_move(root: &ArgMatches<'_>, matches: &ArgMatches<'_>) -> Result<(), String> {
    let path = resolve_config_path_for_read(root)?;
    let mut config = read_config(&path)?;
    ensure_scripts_exist(&config)?;

    let from_alias = matches.value_of("from-alias").unwrap();
    let to_alias = matches.value_of("to-alias").unwrap();
    let force = matches.is_present("force");

    if !force && config.scripts.contains_key(to_alias) {
        return Err(alias_exists_error(to_alias));
    }

    let script = match config.scripts.get(from_alias).cloned() {
        Some(script) => script,
        None => return Err(alias_not_found_error(from_alias)),
    };

    if from_alias != to_alias {
        if force {
            config.scripts.remove(to_alias);
        }
        config.scripts.insert(to_alias.to_owned(), script);
        config.scripts.remove(from_alias);
    }

    write_config(&path, &config)?;
    println!("Move from alias {} to new alias {}", from_alias, to_alias);
    Ok(())
}

fn cmd_remove(root: &ArgMatches<'_>, matches: &ArgMatches<'_>) -> Result<(), String> {
    let path = resolve_config_path_for_read(root)?;
    let mut config = read_config(&path)?;
    ensure_scripts_exist(&config)?;

    let alias = matches.value_of("alias").unwrap();
    if config.scripts.remove(alias).is_none() {
        return Err(alias_not_found_error(alias));
    }

    write_config(&path, &config)?;
    println!("Removed {}", alias);
    Ok(())
}

fn cmd_run(root: &ArgMatches<'_>, matches: &ArgMatches<'_>) -> Result<i32, String> {
    let alias = matches.value_of("alias").unwrap();
    let args = matches
        .values_of("args")
        .map(|values| values.map(ToOwned::to_owned).collect::<Vec<_>>())
        .unwrap_or_default();
    run_alias(root, alias, &args)
}

fn cmd_show(root: &ArgMatches<'_>, matches: &ArgMatches<'_>) -> Result<(), String> {
    let path = resolve_config_path_for_read(root)?;
    let config = read_config(&path)?;
    ensure_scripts_exist(&config)?;

    let alias = matches.value_of("alias").unwrap();
    let script = match config.scripts.get(alias) {
        Some(script) => script,
        None => return Err(alias_not_found_error(alias)),
    };

    println!("{}", script.command);
    Ok(())
}

fn run_alias(root: &ArgMatches<'_>, alias: &str, args: &[String]) -> Result<i32, String> {
    let path = resolve_config_path_for_read(root)?;
    let config = read_config(&path)?;
    ensure_scripts_exist(&config)?;

    let script = match config.scripts.get(alias) {
        Some(script) => script,
        None => return Err(alias_not_found_error(alias)),
    };

    let status = Command::new("sh")
        .arg("-c")
        .arg(&script.command)
        .arg(alias)
        .args(args)
        .status()
        .map_err(|err| format!("Failed to run script {}: {}", alias, err))?;

    Ok(status.code().unwrap_or(1))
}

fn resolve_config_path_for_read(matches: &ArgMatches<'_>) -> Result<PathBuf, String> {
    if let Some(path) = matches.value_of("config-file") {
        return Ok(PathBuf::from(path));
    }

    if let Ok(path) = env::var("PIER_CONFIG_PATH") {
        return Ok(PathBuf::from(path));
    }

    let current_dir = env::current_dir().map_err(|err| err.to_string())?;
    let cwd_candidate = current_dir.join("pier.toml");
    if cwd_candidate.exists() {
        return Ok(cwd_candidate);
    }

    if let Ok(xdg_config_home) = env::var("XDG_CONFIG_HOME") {
        let xdg_base = PathBuf::from(xdg_config_home);
        for candidate in [
            xdg_base.join("pier").join("config.toml"),
            xdg_base.join("pier").join("config"),
            xdg_base.join("pier.toml"),
        ] {
            if candidate.exists() {
                return Ok(candidate);
            }
        }
    }

    if let Ok(home) = env::var("HOME") {
        let home_base = PathBuf::from(home);
        for candidate in [home_base.join(".pier.toml"), home_base.join(".pier")] {
            if candidate.exists() {
                return Ok(candidate);
            }
        }
    }

    Err("No default config file found. See help for more info.".to_owned())
}

fn resolve_config_path_for_init(matches: &ArgMatches<'_>) -> Result<PathBuf, String> {
    if let Some(path) = matches.value_of("config-file") {
        return Ok(PathBuf::from(path));
    }

    if let Ok(path) = env::var("PIER_CONFIG_PATH") {
        return Ok(PathBuf::from(path));
    }

    if let Ok(xdg_config_home) = env::var("XDG_CONFIG_HOME") {
        return Ok(PathBuf::from(xdg_config_home).join("pier").join("config.toml"));
    }

    Err(format!(
        "Failed to create directory. {}",
        io::Error::from(io::ErrorKind::NotFound)
    ))
}

fn read_config(path: &Path) -> Result<ConfigFile, String> {
    let contents = fs::read_to_string(path).map_err(|err| {
        format!(
            "Unable to read config from file {}: {} ",
            path.display(),
            err
        )
    })?;

    toml::from_str::<ConfigFile>(&contents).map_err(|err| {
        format!(
            "Unable to parse toml config from file {}: {}",
            path.display(),
            err
        )
    })
}

fn write_config(path: &Path, config: &ConfigFile) -> Result<(), String> {
    fs::write(path, serialize_config(config)).map_err(|err| {
        format!(
            "Unable to write config to file {}: {}",
            path.display(),
            err
        )
    })
}

fn serialize_config(config: &ConfigFile) -> String {
    let mut out = String::new();

    if config.scripts.is_empty() {
        out.push_str("[scripts]\n\n");
    } else {
        let mut first = true;
        for (alias, script) in &config.scripts {
            if !first {
                out.push('\n');
            }
            first = false;
            out.push_str("[scripts.");
            out.push_str(&serialize_key(alias));
            out.push_str("]\n");
            out.push_str("command = ");
            out.push_str(&serialize_string(&script.command));
            out.push('\n');

            if let Some(description) = &script.description {
                out.push_str("description = ");
                out.push_str(&serialize_string(description));
                out.push('\n');
            }

            if !script.tags.is_empty() {
                out.push_str("tags = [\n");
                for tag in &script.tags {
                    out.push_str("    ");
                    out.push_str(&serialize_string(tag));
                    out.push_str(",\n");
                }
                out.push_str("]\n");
            }
        }
        out.push('\n');
    }

    out.push_str("[default]\n");
    out
}

fn serialize_key(key: &str) -> String {
    if key
        .chars()
        .all(|c| c.is_ascii_alphanumeric() || c == '-' || c == '_')
    {
        key.to_owned()
    } else {
        toml::Value::String(key.to_owned()).to_string()
    }
}

fn serialize_string(value: &str) -> String {
    if !value.contains('\n')
        && !value.contains('\'')
        && !value.contains('\r')
        && !value.chars().any(|c| c.is_control() && c != '\t')
    {
        return format!("'{}'", value);
    }

    if value.contains('\n') && !value.contains('\'') && !value.contains('\r') {
        let mut rendered = String::from("'''\n");
        rendered.push_str(value);
        rendered.push_str("'''");
        return rendered;
    }

    toml::Value::String(value.to_owned()).to_string()
}

fn ensure_scripts_exist(config: &ConfigFile) -> Result<(), String> {
