}

fn alias_exists_error(alias: &str) -> String {
    format!("AliasAlreadyExists:  {}", alias)
}

fn alias_not_found_error(alias: &str) -> String {
    format!("AliasNotFound: No script found by alias {}", alias)
}

fn edit_text(initial: String) -> Result<String, String> {
    let mut temp_file =
        NamedTempFile::new().map_err(|err| format!("EditorError: Failed when trying to get input from editor {}", err))?;

    fs::write(temp_file.path(), initial).map_err(|err| {
        format!(
            "EditorError: Failed when trying to get input from editor {}",
            err
        )
    })?;

    let editor = env::var("EDITOR").unwrap_or_else(|_| "vi".to_owned());
    let status = Command::new(&editor).arg(temp_file.path()).status();
    match status {
        Ok(status) if status.success() => {}
        _ => {
            return Err(format!(
                "EditorError: Failed when trying to get input from editor Failed to open `{}` as a text editor or editor was terminated with errors.",
                editor
            ));
        }
    }

    fs::read_to_string(temp_file.path()).map_err(|err| {
        format!(
            "EditorError: Failed when trying to get input from editor {}",
            err
        )
    })
}

fn listed_scripts(
    config: &ConfigFile,
    tag_filters: &[String],
    cmd_width: Option<usize>,
) -> Vec<ListedScript> {
    let mut scripts = Vec::new();

    if tag_filters.is_empty() {
        for (alias, script) in &config.scripts {
            scripts.push(make_listed_script(alias, script, cmd_width));
        }
        return scripts;
    }

    for tag in tag_filters {
        for (alias, script) in &config.scripts {
            if script.tags.iter().any(|script_tag| script_tag == tag) {
                scripts.push(make_listed_script(alias, script, cmd_width));
            }
        }
    }

    scripts
}

fn make_listed_script(alias: &str, script: &ScriptEntry, cmd_width: Option<usize>) -> ListedScript {
    let mut command_lines = if script.command.is_empty() {
        vec![String::new()]
    } else {
        script.command.lines().map(ToOwned::to_owned).collect::<Vec<_>>()
    };

    if let Some(width) = cmd_width {
        for line in &mut command_lines {
            *line = line.chars().take(width).collect();
        }
    }

    ListedScript {
        alias: alias.to_owned(),
        tags: script.tags.join(","),
        description: script.description.clone().unwrap_or_default(),
        command_lines,
    }
}

fn print_list_table(scripts: &[ListedScript]) {
    let headers = ["Alias", "Tags", "Command", "Description"];

    let mut alias_width = headers[0].len();
    let mut tags_width = headers[1].len();
    let mut command_width = headers[2].len();
    let mut description_width = headers[3].len();

    let mut rows = Vec::new();

    for script in scripts {
        for (index, command_line) in script.command_lines.iter().enumerate() {
            let alias = if index == 0 {
                script.alias.clone()
            } else {
                String::new()
            };
            let tags = if index == 0 {
                script.tags.clone()
            } else {
                String::new()
            };
            let description = if index == 0 {
                script.description.clone()
            } else {
                String::new()
            };

            alias_width = alias_width.max(alias.chars().count());
            tags_width = tags_width.max(tags.chars().count());
            command_width = command_width.max(command_line.chars().count());
            description_width = description_width.max(description.chars().count());

            rows.push((alias, tags, command_line.clone(), description));
        }
    }

    let border_len = alias_width + tags_width + command_width + description_width + 13;
    let border = "≖".repeat(border_len);

    println!("{}", border);
    println!(
        "⋮ {:<alias_width$} ⋮ {:<tags_width$} ⋮ {:<command_width$} ⋮ {:<description_width$} ⋮",
        headers[0],
        headers[1],
        headers[2],
        headers[3],
        alias_width = alias_width,
        tags_width = tags_width,
        command_width = command_width,
        description_width = description_width
    );
    println!("{}", border);

    for (alias, tags, command, description) in rows {
        println!(
            "⋮ {:<alias_width$} ⋮ {:<tags_width$} ⋮ {:<command_width$} ⋮ {:<description_width$} ⋮",
            alias,
            tags,
            command,
            description,
            alias_width = alias_width,
            tags_width = tags_width,
            command_width = command_width,
            description_width = description_width
        );
    }

    println!("{}", border);
}

