+                print!("{}", subcommand_move_help(bin));
+                return Ok(0);
+            }
+            "-V" | "--version" => {
+                println!("{}-move {}", bin, VERSION);
+                return Ok(0);
+            }
+            "-f" | "--force" => {
+                force = true;
+                index += 1;
+                continue;
+            }
+            _ => {
+                if arg.starts_with('-') {
+                    return Err(format!("Found argument '{}' which wasn't expected, or isn't valid in this context", arg));
+                }
+                positionals.push(arg.clone());
+                index += 1;
+            }
+        }
+    }
+
+    if positionals.len() < 2 {
+        print_missing_required(
+            "<from-alias> <to-alias>",
+            &format!("{} move [FLAGS] <from-alias> <to-alias>", bin),
+        );
+        return Ok(1);
+    }
+
+    let from_alias = positionals[0].clone();
+    let to_alias = positionals[1].clone();
+    let path = resolve_config_path_for_read(globals)?;
+    let mut config = read_config(&path)?;
+    ensure_scripts_exist(&config)?;
+
+    if !force && config.scripts.contains_key(&to_alias) {
+        return Err(alias_exists_error(&to_alias));
+    }
+
+    let script = match config.scripts.get(&from_alias).cloned() {
+        Some(script) => script,
+        None => return Err(alias_not_found_error(&from_alias)),
+    };
+
+    if from_alias != to_alias {
+        if force {
+            config.scripts.remove(&to_alias);
+        }
+        config.scripts.insert(to_alias.clone(), script);
+        config.scripts.remove(&from_alias);
+    }
+
+    write_config(&path, &config)?;
+    println!("Move from alias {} to new alias {}", from_alias, to_alias);
+    Ok(0)
+}
+
+fn handle_remove(globals: &GlobalOptions, args: &[String], bin: &str) -> Result<i32, String> {
+    if contains_flag(args, "-h", "--help") {
+        print!("{}", subcommand_remove_help(bin));
+        return Ok(0);
+    }
+    if contains_flag(args, "-V", "--version") {
+        println!("{}-remove {}", bin, VERSION);
+        return Ok(0);
+    }
+    if args.is_empty() {
+        print_missing_required("<alias>", &format!("{} remove <alias>", bin));
+        return Ok(1);
+    }
+
+    let alias = args[0].clone();
+    let path = resolve_config_path_for_read(globals)?;
+    let mut config = read_config(&path)?;
+    ensure_scripts_exist(&config)?;
+
+    if config.scripts.remove(&alias).is_none() {
+        return Err(alias_not_found_error(&alias));
+    }
+
+    write_config(&path, &config)?;
+    println!("Removed {}", alias);
+    Ok(0)
+}
+
+fn handle_run(globals: &GlobalOptions, args: &[String], bin: &str) -> Result<i32, String> {
+    if contains_flag(args, "-h", "--help") {
+        print!("{}", subcommand_run_help(bin));
+        return Ok(0);
+    }
+    if contains_flag(args, "-V", "--version") {
+        println!("{}-run {}", bin, VERSION);
+        return Ok(0);
+    }
+    if args.is_empty() {
+        print_missing_required("<alias>", &format!("{} run <alias> [args]...", bin));
+        return Ok(1);
+    }
+
+    run_alias(globals, &args[0], &args[1..])
+}
