+fn handle_show(globals: &GlobalOptions, args: &[String], bin: &str) -> Result<i32, String> {
+    if contains_flag(args, "-h", "--help") {
+        print!("{}", subcommand_show_help(bin));
+        return Ok(0);
+    }
+    if contains_flag(args, "-V", "--version") {
+        println!("{}-show {}", bin, VERSION);
+        return Ok(0);
+    }
+    if args.is_empty() {
+        print_missing_required("<alias>", &format!("{} show <alias>", bin));
+        return Ok(1);
+    }
+
+    let alias = args[0].clone();
+    let path = resolve_config_path_for_read(globals)?;
+    let config = read_config(&path)?;
+    ensure_scripts_exist(&config)?;
+    let script = match config.scripts.get(&alias) {
+        Some(script) => script,
+        None => return Err(alias_not_found_error(&alias)),
+    };
+    println!("{}", script.command);
