+    if contains_flag(args, "-V", "--version") {
+        println!("{}-edit {}", bin, VERSION);
+        return Ok(0);
+    }
+    if args.is_empty() {
+        print_missing_required("<alias>", &format!("{} edit <alias>", bin));
+        return Ok(1);
+    }
+
+    let alias = args[0].clone();
+    let path = resolve_config_path_for_read(globals)?;
+    let mut config = read_config(&path)?;
+    ensure_scripts_exist(&config)?;
+
+    let existing = match config.scripts.get(&alias).cloned() {
+        Some(script) => script,
+        None => return Err(alias_not_found_error(&alias)),
+    };
+
+    let mut updated = existing;
+    updated.command = edit_text(updated.command)?;
+    config.scripts.insert(alias.clone(), updated);
+    write_config(&path, &config)?;
+    println!("Edited {}", alias);
+    Ok(0)
+}
