use std::collections::BTreeMap;
use std::env;
use std::fs::{self, OpenOptions};
use std::io::{self, Write};
use std::path::{Path, PathBuf};
use std::process::{self, Command};

const VERSION: &str = "0.1.6";
const AUTHORS: &str = "Benjamin Scholtz, Isak Johansson";
const ABOUT: &str = "A simple script management CLI";
const NO_SCRIPTS_ERROR: &str = "No scripts exist. Would you like to add a new script?";

#[derive(Clone, Debug, Default)]
struct ConfigFile {
    scripts: BTreeMap<String, ScriptEntry>,
}

#[derive(Clone, Debug, Default)]
struct ScriptEntry {
    command: String,
    description: Option<String>,
    tags: Vec<String>,
}

#[derive(Clone, Debug, Default)]
struct GlobalOptions {
    config_file: Option<PathBuf>,
    _verbose: usize,
}

#[derive(Clone, Debug)]
struct ListedScript {
    alias: String,
    tags: String,
    description: String,
    command_lines: Vec<String>,
}

fn main() {
    let args = env::args().collect::<Vec<_>>();
    let bin = bin_name(args.first().map(String::as_str).unwrap_or("executable"));

    let exit_code = match handle_root(&args[1..], &bin) {
        Ok(code) => code,
        Err(err) => {
            eprintln!("error: {}", err);
            1
        }
    };

    process::exit(exit_code);
}

fn handle_root(args: &[String], bin: &str) -> Result<i32, String> {
    let mut globals = GlobalOptions::default();
    let mut index = 0usize;

    while index < args.len() {
        let arg = &args[index];
        match arg.as_str() {
            "-h" | "--help" => {
                print!("{}", root_help_long(bin));
                return Ok(0);
            }
            "-V" | "--version" => {
                println!("pier {}", VERSION);
                return Ok(0);
            }
            "--config-file" => {
                let value = next_value(args, index, "--config-file")?;
                globals.config_file = Some(PathBuf::from(value));
                index += 2;
                continue;
            }
            "--verbose" => {
                globals._verbose += 1;
                index += 1;
                continue;
            }
            "--" => {
                if index + 1 >= args.len() {
                    print_root_missing_alias(bin);
                    return Ok(1);
                }
                return run_alias(&globals, &args[index + 1], &args[index + 2..]);
            }
            "help" => {
                return handle_help_subcommand(&args[index + 1..], bin);
            }
            "add" => return handle_add(&globals, &args[index + 1..], bin),
            "config-init" | "init" => return handle_config_init(&globals, &args[index + 1..], bin),
            "copy" | "cp" => return handle_copy(&globals, &args[index + 1..], bin),
            "edit" => return handle_edit(&globals, &args[index + 1..], bin),
            "list" | "ls" => return handle_list(&globals, &args[index + 1..], bin),
            "move" | "mv" | "rename" => return handle_move(&globals, &args[index + 1..], bin),
            "remove" | "rm" => return handle_remove(&globals, &args[index + 1..], bin),
            "run" => return handle_run(&globals, &args[index + 1..], bin),
            "show" => return handle_show(&globals, &args[index + 1..], bin),
            _ => {
                if arg == "-c" || arg.starts_with("-c") {
                    let value = if arg == "-c" {
                        next_value(args, index, "-c")?.to_owned()
                    } else {
                        arg[2..].to_owned()
                    };
                    globals.config_file = Some(PathBuf::from(value));
                    index += if arg == "-c" { 2 } else { 1 };
                    continue;
                }

                if arg.starts_with("-v") && arg.chars().skip(1).all(|ch| ch == 'v') {
                    globals._verbose += arg.len() - 1;
                    index += 1;
                    continue;
                }

                if arg.starts_with('-') {
                    return Err(format!(
                        "Found argument '{}' which wasn't expected, or isn't valid in this context",
                        arg
                    ));
                }

                return run_alias(&globals, arg, &args[index + 1..]);
            }
        }
    }

    print_root_missing_alias(bin);
    Ok(1)
}

fn handle_help_subcommand(args: &[String], bin: &str) -> Result<i32, String> {
    if args.is_empty() {
        print!("{}", root_help_short(bin));
        return Ok(0);
    }

    let text = match canonical_subcommand(&args[0]) {
        Some("add") => subcommand_add_help(bin),
        Some("config-init") => subcommand_config_init_help(bin),
        Some("copy") => subcommand_copy_help(bin),
        Some("edit") => subcommand_edit_help(bin),
        Some("list") => subcommand_list_help(bin),
        Some("move") => subcommand_move_help(bin),
        Some("remove") => subcommand_remove_help(bin),
        Some("run") => subcommand_run_help(bin),
        Some("show") => subcommand_show_help(bin),
        _ => root_help_short(bin),
    };

    print!("{}", text);
    Ok(0)
}

fn handle_add(globals: &GlobalOptions, args: &[String], bin: &str) -> Result<i32, String> {
    let mut alias: Option<String> = None;
    let mut description: Option<String> = None;
    let mut tags = Vec::new();
    let mut force = false;
    let mut command: Option<String> = None;
    let mut index = 0usize;
    let mut positional = false;

    while index < args.len() {
        let arg = &args[index];

        if !positional {
            match arg.as_str() {
                "-h" | "--help" => {
                    print!("{}", subcommand_add_help(bin));
                    return Ok(0);
                }
                "-V" | "--version" => {
                    println!("{}-add {}", bin, VERSION);
                    return Ok(0);
                }
                "-f" | "--force" => {
                    force = true;
                    index += 1;
                    continue;
                }
                "-a" | "--alias" => {
                    alias = Some(next_value(args, index, arg)?.to_owned());
                    index += 2;
                    continue;
                }
                "-d" | "--description" => {
                    description = Some(next_value(args, index, arg)?.to_owned());
                    index += 2;
                    continue;
                }
                "-t" | "--tag" => {
                    let (values, next) = consume_greedy_values(args, index)?;
                    tags.extend(values);
                    index = next;
                    continue;
                }
                "--" => {
                    positional = true;
                    index += 1;
                    continue;
                }
                _ => {
                    if let Some(value) = arg.strip_prefix("--alias=") {
                        alias = Some(value.to_owned());
                        index += 1;
                        continue;
                    }
                    if let Some(value) = arg.strip_prefix("--description=") {
                        description = Some(value.to_owned());
                        index += 1;
                        continue;
                    }
                    if let Some(value) = arg.strip_prefix("--tag=") {
                        tags.push(value.to_owned());
                        index += 1;
                        continue;
                    }
                    if arg.starts_with("-a") && arg.len() > 2 {
                        alias = Some(arg[2..].to_owned());
                        index += 1;
                        continue;
                    }
                    if arg.starts_with("-d") && arg.len() > 2 {
                        description = Some(arg[2..].to_owned());
                        index += 1;
                        continue;
                    }
                    if arg.starts_with("-t") && arg.len() > 2 {
                        tags.push(arg[2..].to_owned());
                        index += 1;
                        continue;
                    }
                    if arg.starts_with('-') {
                        return Err(format!(
                            "Found argument '{}' which wasn't expected, or isn't valid in this context",
                            arg
                        ));
                    }

                    command = Some(arg.clone());
                    break;
                }
            }
        } else {
            command = Some(arg.clone());
            break;
        }
    }

    if alias.is_none() {
        print_missing_required(
            "--alias <alias>",
            &format!("{} add [FLAGS] [OPTIONS] --alias <alias> [--] [command]", bin),
        );
        return Ok(1);
    }

    let path = resolve_config_path_for_read(globals)?;
    let mut config = read_config(&path)?;
    let alias = alias.unwrap();

    if config.scripts.contains_key(&alias) && !force {
        return Err(alias_exists_error(&alias));
    }

    let command = match command {
        Some(command) => command,
        None => edit_text("".to_owned())?,
    };

    config.scripts.insert(
        alias.clone(),
        ScriptEntry {
            command,
            description,
            tags,
        },
    );
    write_config(&path, &config)?;
    println!("Added {}", alias);
    Ok(0)
}

fn handle_config_init(globals: &GlobalOptions, args: &[String], bin: &str) -> Result<i32, String> {
    if contains_flag(args, "-h", "--help") {
        print!("{}", subcommand_config_init_help(bin));
        return Ok(0);
    }
    if contains_flag(args, "-V", "--version") {
        println!("{}-config-init {}", bin, VERSION);
        return Ok(0);
    }
    if !args.is_empty() {
        return Err(format!(
            "Found argument '{}' which wasn't expected, or isn't valid in this context",
            args[0]
        ));
    }

    let path = resolve_config_path_for_init(globals)?;
    if path.exists() {
        return Err(format!(
            "Cannot initialize config at {}, file already exists.",
            path.display()
        ));
    }

    if let Some(parent) = path.parent() {
        if !parent.as_os_str().is_empty() && !parent.exists() {
            fs::create_dir(parent)
                .map_err(|err| format!("Failed to create directory. {}", err))?;
        }
    }

    let mut config = ConfigFile::default();
    config.scripts.insert(
        "hello-pier".to_owned(),
        ScriptEntry {
            command: "echo Hello, Pier!".to_owned(),
            description: Some("This is an example command.".to_owned()),
            tags: Vec::new(),
        },
    );
    write_config(&path, &config)?;
    println!("Added hello-pier");
    Ok(0)
}

fn handle_copy(globals: &GlobalOptions, args: &[String], bin: &str) -> Result<i32, String> {
