fn handle_list(globals: &GlobalOptions, args: &[String], bin: &str) -> Result<i32, String> {
    let mut cmd_width: Option<usize> = None;
    let mut list_aliases = false;
    let mut tags = Vec::new();
    let mut index = 0usize;

    while index < args.len() {
        let arg = &args[index];
        match arg.as_str() {
            "-h" | "--help" => {
                print!("{}", subcommand_list_help(bin));
                return Ok(0);
            }
            "-V" | "--version" => {
                println!("{}-list {}", bin, VERSION);
                return Ok(0);
            }
            "-l" | "--cmd_full" => {
                index += 1;
                continue;
            }
            "-q" | "--list_aliases" => {
                list_aliases = true;
                index += 1;
                continue;
            }
            "-c" | "--cmd_width" => {
                let value = next_value(args, index, arg)?;
                cmd_width = value.parse::<usize>().ok();
                index += 2;
                continue;
            }
            "-t" | "--tag" => {
                let (values, next) = consume_greedy_values(args, index)?;
                tags.extend(values);
                index = next;
                continue;
            }
            _ => {
                if let Some(value) = arg.strip_prefix("--cmd_width=") {
                    cmd_width = value.parse::<usize>().ok();
                    index += 1;
                    continue;
                }
                if let Some(value) = arg.strip_prefix("--tag=") {
                    tags.push(value.to_owned());
                    index += 1;
                    continue;
                }
                if arg.starts_with("-c") && arg.len() > 2 {
                    cmd_width = arg[2..].parse::<usize>().ok();
                    index += 1;
                    continue;
                }
                if arg.starts_with("-t") && arg.len() > 2 {
                    tags.push(arg[2..].to_owned());
                    index += 1;
                    continue;
                }
                return Err(format!(
                    "Found argument '{}' which wasn't expected, or isn't valid in this context",
                    arg
                ));
            }
        }
    }

    let path = resolve_config_path_for_read(globals)?;
    let config = read_config(&path)?;
    ensure_scripts_exist(&config)?;
    let scripts = listed_scripts(&config, &tags, cmd_width);

    if list_aliases {
        for script in scripts {
            println!("{}", script.alias);
        }
        return Ok(0);
    }

    print_list_table(&scripts);
    Ok(0)
}

fn handle_move(globals: &GlobalOptions, args: &[String], bin: &str) -> Result<i32, String> {
    let mut force = false;
    let mut positionals = Vec::new();
    let mut index = 0usize;

    while index < args.len() {
        let arg = &args[index];
        match arg.as_str() {
            "-h" | "--help" => {
                print!("{}", subcommand_move_help(bin));
                return Ok(0);
            }
            "-V" | "--version" => {
                println!("{}-move {}", bin, VERSION);
                return Ok(0);
            }
            "-f" | "--force" => {
                force = true;
                index += 1;
                continue;
            }
            _ => {
                if arg.starts_with('-') {
                    return Err(format!(
                        "Found argument '{}' which wasn't expected, or isn't valid in this context",
                        arg
                    ));
                }
                positionals.push(arg.clone());
                index += 1;
            }
        }
    }

    if positionals.len() < 2 {
        print_missing_required(
            "<from-alias> <to-alias>",
            &format!("{} move [FLAGS] <from-alias> <to-alias>", bin),
        );
        return Ok(1);
    }

    let from_alias = positionals[0].clone();
    let to_alias = positionals[1].clone();
    let path = resolve_config_path_for_read(globals)?;
    let mut config = read_config(&path)?;
    ensure_scripts_exist(&config)?;

    if !force && config.scripts.contains_key(&to_alias) {
        return Err(alias_exists_error(&to_alias));
    }

    let script = match config.scripts.get(&from_alias).cloned() {
        Some(script) => script,
        None => return Err(alias_not_found_error(&from_alias)),
    };

    if from_alias != to_alias {
        if force {
            config.scripts.remove(&to_alias);
        }
        config.scripts.insert(to_alias.clone(), script);
        config.scripts.remove(&from_alias);
    }

    write_config(&path, &config)?;
    println!("Move from alias {} to new alias {}", from_alias, to_alias);
    Ok(0)
}

