fn resolve_config_path_for_read(globals: &GlobalOptions) -> Result<PathBuf, String> {
    if let Some(path) = &globals.config_file {
        return Ok(path.clone());
    }

    if let Ok(path) = env::var("PIER_CONFIG_PATH") {
        return Ok(PathBuf::from(path));
    }

    let cwd = env::current_dir().map_err(|err| err.to_string())?;
    let candidate = cwd.join("pier.toml");
    if candidate.exists() {
        return Ok(candidate);
    }

    if let Ok(xdg_config_home) = env::var("XDG_CONFIG_HOME") {
        let base = PathBuf::from(xdg_config_home);
        for candidate in [
            base.join("pier").join("config.toml"),
            base.join("pier").join("config"),
            base.join("pier.toml"),
        ] {
            if candidate.exists() {
                return Ok(candidate);
            }
        }
    }

    if let Ok(home) = env::var("HOME") {
        let base = PathBuf::from(home);
        for candidate in [base.join(".pier.toml"), base.join(".pier")] {
            if candidate.exists() {
                return Ok(candidate);
            }
        }
    }

    Err("No default config file found. See help for more info.".to_owned())
}

fn resolve_config_path_for_init(globals: &GlobalOptions) -> Result<PathBuf, String> {
    if let Some(path) = &globals.config_file {
        return Ok(path.clone());
    }
    if let Ok(path) = env::var("PIER_CONFIG_PATH") {
        return Ok(PathBuf::from(path));
    }
    if let Ok(xdg_config_home) = env::var("XDG_CONFIG_HOME") {
        return Ok(PathBuf::from(xdg_config_home).join("pier").join("config.toml"));
    }

    Err(format!(
        "Failed to create directory. {}",
        io::Error::from(io::ErrorKind::NotFound)
    ))
}

fn read_config(path: &Path) -> Result<ConfigFile, String> {
    let contents = fs::read_to_string(path).map_err(|err| {
        format!(
            "Unable to read config from file {}: {} ",
            path.display(),
            err
        )
    })?;

    parse_config(&contents).map_err(|err| {
        format!(
            "Unable to parse toml config from file {}: {}",
            path.display(),
            err
        )
    })
}

fn parse_config(contents: &str) -> Result<ConfigFile, String> {
    #[derive(Clone)]
    enum Section {
        Root,
        Script(String),
        Default,
        Ignore,
    }

    let mut config = ConfigFile::default();
    let lines = contents.lines().collect::<Vec<_>>();
    let mut section = Section::Root;
    let mut index = 0usize;

    while index < lines.len() {
        let line = lines[index];
        let trimmed = line.trim();

        if trimmed.is_empty() || trimmed.starts_with('#') {
            index += 1;
            continue;
        }

        if trimmed.starts_with('[') {
            if trimmed == "[default]" || trimmed == "[scripts]" {
                section = Section::Default;
                index += 1;
                continue;
            }
            if trimmed.starts_with("[scripts.") && trimmed.ends_with(']') {
                let raw_alias = &trimmed["[scripts.".len()..trimmed.len() - 1];
                let alias = parse_table_key(raw_alias, index + 1)?;
                config.scripts.entry(alias.clone()).or_default();
                section = Section::Script(alias);
                index += 1;
                continue;
            }

            section = Section::Ignore;
            index += 1;
            continue;
        }

        let eq_pos = line.find('=').ok_or_else(|| parse_missing_equals(trimmed, index + 1))?;
        let key = line[..eq_pos].trim();
        let value = line[eq_pos + 1..].trim_start();

        if let Section::Script(alias) = &section {
            let script = config.scripts.entry(alias.clone()).or_default();
            match key {
                "command" => {
                    let (parsed, next_index) = parse_string_value(&lines, index, value)?;
                    script.command = parsed;
                    index = next_index;
                    continue;
                }
                "description" => {
                    let (parsed, next_index) = parse_string_value(&lines, index, value)?;
                    script.description = Some(parsed);
                    index = next_index;
                    continue;
                }
                "tags" => {
                    let (parsed, next_index) = parse_tags_value(&lines, index, value)?;
                    script.tags = parsed;
                    index = next_index;
                    continue;
                }
                _ => {}
            }
        }

        index += 1;
    }

    Ok(config)
}

fn parse_table_key(raw: &str, line_no: usize) -> Result<String, String> {
    let trimmed = raw.trim();
    if trimmed.starts_with('"') {
        parse_basic_string(trimmed, line_no)
    } else {
        Ok(trimmed.to_owned())
    }
}

fn parse_string_value(lines: &[&str], index: usize, value: &str) -> Result<(String, usize), String> {
    let trimmed = value.trim();
    if trimmed.starts_with("'''") {
        return parse_multiline_literal_string(lines, index, trimmed);
    }
    if trimmed.starts_with('\'') {
        return parse_single_line_literal_string(trimmed, index + 1).map(|value| (value, index + 1));
    }
    if trimmed.starts_with('"') {
        return parse_basic_string(trimmed, index + 1).map(|value| (value, index + 1));
    }

    Err(format!("unsupported value at line {}", index + 1))
}

fn parse_multiline_literal_string(lines: &[&str], index: usize, value: &str) -> Result<(String, usize), String> {
    let after_open = &value[3..];
    if let Some(end) = after_open.find("'''") {
        return Ok((after_open[..end].to_owned(), index + 1));
    }

    let mut parsed = String::new();
    if !after_open.is_empty() {
        parsed.push_str(after_open);
        parsed.push('\n');
    }

    let mut cursor = index + 1;
    while cursor < lines.len() {
        let line = lines[cursor];
        if let Some(end) = line.find("'''") {
            parsed.push_str(&line[..end]);
            return Ok((parsed, cursor + 1));
        }
        parsed.push_str(line);
        parsed.push('\n');
        cursor += 1;
    }

    Err(format!("unterminated literal string at line {}", index + 1))
}

fn parse_single_line_literal_string(value: &str, line_no: usize) -> Result<String, String> {
    let end = value[1..]
        .find('\'')
        .map(|pos| pos + 1)
        .ok_or_else(|| format!("unterminated literal string at line {}", line_no))?;
    Ok(value[1..end].to_owned())
}

fn parse_basic_string(value: &str, line_no: usize) -> Result<String, String> {
    let bytes = value.as_bytes();
    if bytes.first().copied() != Some(b'"') {
        return Err(format!("invalid string at line {}", line_no));
    }

    let mut escaped = false;
    let mut rendered = String::new();
    let mut index = 1usize;

    while index < bytes.len() {
        let ch = bytes[index] as char;
        if escaped {
            let decoded = match ch {
                'n' => '\n',
                'r' => '\r',
                't' => '\t',
                '"' => '"',
                '\\' => '\\',
                other => other,
            };
            rendered.push(decoded);
            escaped = false;
            index += 1;
            continue;
        }

        if ch == '\\' {
            escaped = true;
            index += 1;
            continue;
        }
        if ch == '"' {
            return Ok(rendered);
        }

        rendered.push(ch);
        index += 1;
    }

    Err(format!("unterminated basic string at line {}", line_no))
}

fn parse_tags_value(lines: &[&str], index: usize, value: &str) -> Result<(Vec<String>, usize), String> {
    let trimmed = value.trim();
    if trimmed == "[]" {
        return Ok((Vec::new(), index + 1));
    }
    if !trimmed.starts_with('[') {
        return Err(format!("invalid array at line {}", index + 1));
    }

    let mut tags = Vec::new();
    let remainder = trimmed[1..].trim();
    if remainder == "]" {
        return Ok((tags, index + 1));
    }
    if !remainder.is_empty() && remainder.ends_with(']') {
        let content = remainder[..remainder.len() - 1].trim();
        if !content.is_empty() {
            for piece in content.split(',').filter(|piece| !piece.trim().is_empty()) {
                tags.push(parse_inline_string(piece.trim(), index + 1)?);
            }
        }
        return Ok((tags, index + 1));
    }

    let mut cursor = index + 1;
    while cursor < lines.len() {
        let trimmed_line = lines[cursor].trim();
        if trimmed_line == "]" {
            return Ok((tags, cursor + 1));
        }
        let item = trimmed_line.trim_end_matches(',').trim();
        if !item.is_empty() {
            tags.push(parse_inline_string(item, cursor + 1)?);
        }
        cursor += 1;
    }

    Err(format!("unterminated array at line {}", index + 1))
}

fn parse_inline_string(value: &str, line_no: usize) -> Result<String, String> {
    if value.starts_with('\'') {
        parse_single_line_literal_string(value, line_no)
    } else if value.starts_with('"') {
        parse_basic_string(value, line_no)
    } else {
        Err(format!("invalid string at line {}", line_no))
    }
}

fn parse_missing_equals(trimmed: &str, line_no: usize) -> String {
    if trimmed
        .split_whitespace()
        .next()
        .map(|token| {
            token
                .chars()
                .all(|ch| ch.is_ascii_alphanumeric() || ch == '_' || ch == '-')
        })
        .unwrap_or(false)
    {
        format!("expected an equals, found an identifier at line {}", line_no)
    } else {
        format!("invalid line at {}", line_no)
    }
}

fn write_config(path: &Path, config: &ConfigFile) -> Result<(), String> {
    fs::write(path, serialize_config(config)).map_err(|err| {
        format!(
            "Unable to write config to file {}: {}",
            path.display(),
            err
        )
    })
}

fn serialize_config(config: &ConfigFile) -> String {
    let mut out = String::new();

    if config.scripts.is_empty() {
        out.push_str("[scripts]\n\n");
    } else {
        let mut first = true;
        for (alias, script) in &config.scripts {
            if !first {
                out.push('\n');
            }
            first = false;
            out.push_str("[scripts.");
            out.push_str(&serialize_key(alias));
            out.push_str("]\n");
            out.push_str("command = ");
            out.push_str(&serialize_string(&script.command));
            out.push('\n');

            if let Some(description) = &script.description {
                out.push_str("description = ");
                out.push_str(&serialize_string(description));
                out.push('\n');
            }

            if !script.tags.is_empty() {
                out.push_str("tags = [\n");
                for tag in &script.tags {
                    out.push_str("    ");
                    out.push_str(&serialize_string(tag));
                    out.push_str(",\n");
                }
                out.push_str("]\n");
            }
        }
        out.push('\n');
    }

    out.push_str("[default]\n");
    out
}

fn serialize_key(key: &str) -> String {
    if key
        .chars()
        .all(|ch| ch.is_ascii_alphanumeric() || ch == '-' || ch == '_')
    {
        key.to_owned()
    } else {
        format!("\"{}\"", escape_basic_string(key))
    }
}

fn serialize_string(value: &str) -> String {
    if !value.contains('\n')
        && !value.contains('\'')
        && !value.contains('\r')
        && !value.chars().any(|ch| ch.is_control() && ch != '\t')
    {
        return format!("'{}'", value);
    }

    if value.contains('\n') && !value.contains('\'') && !value.contains('\r') {
        let mut rendered = String::from("'''\n");
        rendered.push_str(value);
        rendered.push_str("'''");
        return rendered;
    }

    format!("\"{}\"", escape_basic_string(value))
}

fn escape_basic_string(value: &str) -> String {
    let mut rendered = String::new();
    for ch in value.chars() {
        match ch {
            '\\' => rendered.push_str("\\\\"),
            '"' => rendered.push_str("\\\""),
            '\n' => rendered.push_str("\\n"),
            '\r' => rendered.push_str("\\r"),
            '\t' => rendered.push_str("\\t"),
            other => rendered.push(other),
        }
    }
    rendered
}

fn ensure_scripts_exist(config: &ConfigFile) -> Result<(), String> {
    if config.scripts.is_empty() {
        Err(NO_SCRIPTS_ERROR.to_owned())
    } else {
        Ok(())
    }
}

fn alias_exists_error(alias: &str) -> String {
    format!("AliasAlreadyExists:  {}", alias)
}

fn alias_not_found_error(alias: &str) -> String {
    format!("AliasNotFound: No script found by alias {}", alias)
}

fn edit_text(initial: String) -> Result<String, String> {
    let temp_dir = env::temp_dir();
    let mut attempt = 0u32;

    loop {
        let path = temp_dir.join(format!("xvrqt_scrawl_{}_{}", process::id(), attempt));
        let file = OpenOptions::new().write(true).create_new(true).open(&path);
        let mut file = match file {
            Ok(file) => file,
            Err(err) if err.kind() == io::ErrorKind::AlreadyExists => {
                attempt += 1;
                continue;
            }
            Err(err) => {
                return Err(format!(
                    "EditorError: Failed when trying to get input from editor {}",
                    err
                ));
            }
        };

        file.write_all(initial.as_bytes()).map_err(|err| {
            format!(
                "EditorError: Failed when trying to get input from editor {}",
                err
            )
        })?;
        drop(file);

        let editor = env::var("EDITOR").unwrap_or_else(|_| "vi".to_owned());
        let status = Command::new(&editor).arg(&path).status();
        match status {
            Ok(status) if status.success() => {
                let result = fs::read_to_string(&path).map_err(|err| {
                    format!(
                        "EditorError: Failed when trying to get input from editor {}",
                        err
                    )
