fn open_editor(initial: String) -> Result<String, String> {
    let editor = env::var("VISUAL")
        .or_else(|_| env::var("EDITOR"))
        .unwrap_or_else(|_| "vi".to_string());
    let path = temp_edit_path();

    if let Err(error) = fs::write(&path, initial) {
        return Err(format!(
            "Unable to prepare temporary edit buffer {}: {}",
            path.display(),
            error
        ));
    }

    let status = Command::new(&editor).arg(&path).status();
    match status {
        Ok(status) if status.success() => {}
        Ok(_) | Err(_) => {
            let _ = fs::remove_file(&path);
            return Err(format!(
                "EditorError: Failed when trying to get input from editor Failed to open `{}` as a text editor or editor was terminated with errors.",
                editor
            ));
        }
    }

    let updated = fs::read_to_string(&path).map_err(|error| {
        format!(
            "Unable to read edited content from {}: {}",
            path.display(),
            error
        )
    })?;
    let _ = fs::remove_file(&path);
    Ok(updated)
}

fn temp_edit_path() -> PathBuf {
    let base = env::temp_dir();
    let counter = TEMP_COUNTER.fetch_add(1, AtomicOrdering::Relaxed);
    let nanos = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map(|duration| duration.as_nanos())
        .unwrap_or(0);
    base.join(format!(
        "xvrqt_scrawl_{}_{}_{}",
        process::id(),
        nanos,
        counter
    ))
}

fn collect_scripts_for_list<'a>(
    config: &'a Config,
    filter_tags: Option<&[String]>,
) -> Vec<(&'a String, &'a Script)> {
    match filter_tags {
        None => config.scripts.iter().collect(),
        Some(tags) => {
            let mut rows = Vec::new();
            for tag in tags {
                for (alias, script) in &config.scripts {
                    if script
                        .tags
                        .as_ref()
                        .map(|values| values.iter().any(|value| value == tag))
                        .unwrap_or(false)
                    {
                        rows.push((alias, script));
                    }
                }
            }
            rows
        }
    }
}

