    Err(format!("invalid value `{}` for key `{}`", value, key_path))
}

fn parse_multiline_literal_string(
    lines: &[&str],
    start_index: usize,
    rest: &str,
) -> Result<(String, usize), String> {
    if let Some(end) = rest.find("'''") {
        return Ok((rest[..end].to_string(), start_index));
    }

    let mut value = String::new();
    if !rest.is_empty() {
        value.push_str(rest);
        value.push('\n');
    }

    let mut index = start_index + 1;
    while index < lines.len() {
        let line = lines[index];
        if let Some(end) = line.find("'''") {
            value.push_str(&line[..end]);
            return Ok((value, index));
        }
        value.push_str(line);
        value.push('\n');
        index += 1;
    }

    Err(format!(
        "unterminated multi-line string at line {}",
        start_index + 1
    ))
}

fn parse_multiline_basic_string(
    lines: &[&str],
    start_index: usize,
    rest: &str,
) -> Result<(String, usize), String> {
    if let Some(end) = rest.find("\"\"\"") {
        return Ok((parse_basic_string(&rest[..end])?, start_index));
    }

    let mut value = String::new();
    if !rest.is_empty() {
        value.push_str(rest);
        value.push('\n');
    }

    let mut index = start_index + 1;
    while index < lines.len() {
        let line = lines[index];
        if let Some(end) = line.find("\"\"\"") {
            value.push_str(&line[..end]);
            return Ok((parse_basic_string(&value)?, index));
        }
        value.push_str(line);
        value.push('\n');
        index += 1;
    }

    Err(format!(
        "unterminated multi-line string at line {}",
        start_index + 1
    ))
}

fn parse_basic_string(raw: &str) -> Result<String, String> {
    let mut out = String::new();
    let mut chars = raw.chars();
    while let Some(ch) = chars.next() {
        if ch == '\\' {
            let escaped = chars.next().ok_or_else(|| "unterminated escape sequence".to_string())?;
            match escaped {
                'n' => out.push('\n'),
                'r' => out.push('\r'),
                't' => out.push('\t'),
                '\\' => out.push('\\'),
                '"' => out.push('"'),
                other => out.push(other),
            }
        } else {
            out.push(ch);
        }
    }
    Ok(out)
}

fn parse_toml_string_array(
    lines: &[&str],
    start_index: usize,
    value: &str,
    key_path: &str,
) -> Result<(Vec<String>, usize), String> {
    let trimmed = value.trim();
    if trimmed == "[]" {
        return Ok((Vec::new(), start_index));
    }
    if trimmed.starts_with('[') && trimmed.ends_with(']') {
        let inner = &trimmed[1..trimmed.len() - 1];
        if inner.trim().is_empty() {
            return Ok((Vec::new(), start_index));
        }
        return Ok((parse_inline_string_array(inner, key_path)?, start_index));
